require('dotenv').config();
const express = require('express');
const cors = require('cors');
const multer = require('multer');
const { createClient } = require('@supabase/supabase-js');

const app = express();
app.use(cors());
app.use(express.json());
app.use(express.static('public')); // Membaca file HTML di folder public

// Inisialisasi Supabase menggunakan URL & Key dari file .env
const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_KEY);

// Konfigurasi Multer untuk menangani file gambar poster
const storage = multer.memoryStorage();
const upload = multer({ storage: storage });

// Data sementara (Database lokal di memori)
let movies = [
  {
    id: 1,
    title: "Inception",
    price: 50000,
    seatsAvailable: 30,
    posterUrl: "https://via.placeholder.com/300x400"
  }
];

// API: Ambil daftar film
app.get('/api/movies', (req, res) => {
  res.json(movies);
});

// API: Tambah film baru + Upload gambar poster ke Supabase Block Storage
app.post('/api/movies', upload.single('poster'), async (req, res) => {
  try {
    const { title, price, seatsAvailable } = req.body;
    let posterUrl = "https://via.placeholder.com/300x400";

    if (req.file) {
      const fileName = `posters/${Date.now()}_${req.file.originalname}`;
      
      // Upload ke Supabase Storage Bucket bernama 'posters'
      const { error } = await supabase.storage
        .from('posters')
        .upload(fileName, req.file.buffer, {
          contentType: req.file.mimetype,
          upsert: true
        });

      if (error) throw error;

      // Ambil Link Publik (Public URL) dari gambar yang diupload
      const { data: publicUrlData } = supabase.storage
        .from('posters')
        .getPublicUrl(fileName);

      posterUrl = publicUrlData.publicUrl;
    }

    const newMovie = {
      id: movies.length + 1,
      title,
      price: parseInt(price),
      seatsAvailable: parseInt(seatsAvailable),
      posterUrl
    };

    movies.push(newMovie);
    res.json({ success: true, movie: newMovie });
  } catch (err) {
    res.status(500).json({ success: false, message: err.message });
  }
});

// API: Pesan tiket bioskop
app.post('/api/book', (req, res) => {
  const { movieId, seatsBooked } = req.body;
  const movie = movies.find(m => m.id === movieId);
  
  if (!movie) return res.status(404).json({ message: "Film tidak ditemukan" });
  if (movie.seatsAvailable < seatsBooked) {
    return res.status(400).json({ message: "Kursi tidak mencukupi!" });
  }

  movie.seatsAvailable -= seatsBooked;
  res.json({ success: true, message: "Pemesanan tiket berhasil!", remainingSeats: movie.seatsAvailable });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server berjalan lancar di http://localhost:${PORT}`);
});